from pathlib import Path
import json,base64,html
R=Path(__file__).resolve().parents[1]
states=['idle','warning','breaking','falling','settling','collapsed'];names=['תקין','אזהרה','שבירה','נפילה','התייצבות','משטח מוכן']
images={}
for prefix,phases in [('M473_BEFORE',['IDLE','WARNING','COLLAPSED']),('M474_AFTER',[s.upper() for s in states])]:
 for state in phases:images[prefix+'_'+state]='data:image/png;base64,'+base64.b64encode((R/'evidence'/f'{prefix}_{state}.png').read_bytes()).decode()
records=json.loads((R/'evidence/m474-visual.json').read_text())['records'];poses={r['state']:r['snapshot']['tree'] for r in records if r['prefix']=='M474_AFTER'}
buttons=''.join(f'<button onclick="show({i})" id="b{i}">{n}</button>' for i,n in enumerate(names))
body='''<!doctype html><html lang="he" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>האחים רפאל — M4.7.4 השוואה חזותית</title><style>body{margin:0;background:#0c211e;color:#f0edda;font:16px system-ui,sans-serif}main{max-width:1700px;margin:auto;padding:24px}h1{font-size:26px}p{max-width:1050px;line-height:1.6;color:#c4d2c6}nav{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}button{background:#213e35;color:#eee2bc;border:1px solid #718c6a;padding:12px 18px;border-radius:8px;cursor:pointer}button.active{background:#d3b16a;color:#15251f}section{display:grid;grid-template-columns:1fr 1fr;gap:16px}article{background:#122d26;padding:12px;border-radius:12px}img{width:100%;display:block;cursor:zoom-in}img.large{position:fixed;inset:5vh 2vw;width:96vw;height:90vh;object-fit:contain;background:#071a16;z-index:4;cursor:zoom-out}h2{margin:5px 0 10px;font-size:19px}code{direction:ltr;display:block;white-space:pre-wrap;color:#d8c68a;padding:15px;background:#071a16;border-radius:8px}small{display:block;margin:12px 0;color:#acbbae}@media(max-width:900px){section{grid-template-columns:1fr}}</style><main><h1>M4.7.4 — הגזע הראשון: לפני / אחרי</h1><p>מצלמה קבועה באותו מיקום (0,0), חלון 1280×720 ודמות בנקודת התחלה זהה. כל שלב הושג במעבר מצב טבעי; המשחק הוקפא לצילום בלבד. אלה ראיות חזותיות ואינן תחליף לרצפי המקלדת שבדוח QA. בגרסה הקודמת אין שלבי נפילה ביניים, ולכן במצבים אלה משמאל מוצגת התוצאה הישנה.</p><nav>'''+buttons+'''</nav><section><article><h2>M4.7.3 — לפני</h2><img id="old" alt="הגרסה הקודמת" onclick="this.classList.toggle('large')"></article><article><h2 id="heading">M4.7.4 — אחרי</h2><img id="new" alt="הגזע הרציף בגרסה החדשה" onclick="this.classList.toggle('large')"></article></section><small>השורשים הירוקים התלויים הם דקורציה ללא קולידרים; משטח הגזע החדש מופעל רק לאחר התייצבות. הגזע השני כבוי כברירת מחדל, ושער הסיום אינו תלוי בהפעלתו.</small><code id="data"></code></main><script>'''
js='const images='+json.dumps(images)+';const states='+json.dumps(states)+';const names='+json.dumps(names,ensure_ascii=False)+';const poses='+json.dumps(poses)+';function show(i){const s=states[i],before=s==="idle"?"IDLE":s==="warning"?"WARNING":"COLLAPSED";document.getElementById("old").src=images["M473_BEFORE_"+before];document.getElementById("new").src=images["M474_AFTER_"+s.toUpperCase()];document.getElementById("heading").textContent="M4.7.4 — "+names[i];document.querySelectorAll("button").forEach((b,n)=>b.classList.toggle("active",n===i));const a=poses[s];document.getElementById("data").textContent=JSON.stringify({state:a.state,anchorActive:a.anchorActive,platformActive:a.platformActive,pivot:a.pose.pivot,logLength:a.pose.length,deck:a.geometry},null,2);}show(0);'
(R/'M474_VISUAL_COMPARISON.html').write_text(body+js+'</script></html>')
print('Self-contained comparison gallery:',(R/'M474_VISUAL_COMPARISON.html').stat().st_size,'bytes')
